-- Accounts & Collections Agent V1 foundation.
insert into public.agent_types(key,display_name,system_managed,description) values ('accounts_collections_agent','Accounts & Collections Agent',true,'Organisation-scoped payment reminder and collections employee.') on conflict (key) do nothing;
create table if not exists public.collection_policies (id uuid primary key default gen_random_uuid(),organisation_id uuid not null references public.organisations(id) on delete cascade,reminder_before_due_days integer not null default 3,reminder_after_due_days integer not null default 1,maximum_automatic_reminders integer not null default 2,automatic_sending_enabled boolean not null default false,final_demand_requires_approval boolean not null default true,tone text not null default 'professional',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organisation_id));
create table if not exists public.invoices (id uuid primary key default gen_random_uuid(),organisation_id uuid not null references public.organisations(id) on delete cascade,contact_id uuid not null references public.crm_contacts(id),invoice_number text not null,issue_date date not null,due_date date not null,currency text not null default 'ZAR',total_amount numeric(14,2) not null check(total_amount>=0),status text not null default 'issued' check(status in ('draft','issued','partially_paid','paid','overdue','cancelled')),notes text,source_metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organisation_id,invoice_number));
create table if not exists public.invoice_payments (id uuid primary key default gen_random_uuid(),organisation_id uuid not null references public.organisations(id) on delete cascade,invoice_id uuid not null references public.invoices(id) on delete cascade,contact_id uuid not null references public.crm_contacts(id),amount numeric(14,2) not null check(amount>0),payment_date date not null,payment_method text,payment_reference text,status text not null default 'confirmed' check(status in ('pending','confirmed','reversed')),external_reference text,created_at timestamptz not null default now());
create table if not exists public.collection_activity (id uuid primary key default gen_random_uuid(),organisation_id uuid not null references public.organisations(id) on delete cascade,invoice_id uuid references public.invoices(id) on delete set null,contact_id uuid references public.crm_contacts(id) on delete set null,activity_type text not null,channel text,stage text,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index if not exists invoices_org_due_idx on public.invoices(organisation_id,due_date);create index if not exists invoice_payments_invoice_idx on public.invoice_payments(invoice_id);create index if not exists collection_activity_org_idx on public.collection_activity(organisation_id,created_at desc);
alter table public.collection_policies enable row level security;alter table public.invoices enable row level security;alter table public.invoice_payments enable row level security;alter table public.collection_activity enable row level security;
create policy "members read collection policies" on public.collection_policies for select to authenticated using(private.is_active_member(organisation_id));create policy "members manage collection policies" on public.collection_policies for all to authenticated using(private.is_active_member(organisation_id)) with check(private.is_active_member(organisation_id));
create policy "members manage invoices" on public.invoices for all to authenticated using(private.is_active_member(organisation_id)) with check(private.is_active_member(organisation_id));create policy "members manage invoice payments" on public.invoice_payments for all to authenticated using(private.is_active_member(organisation_id)) with check(private.is_active_member(organisation_id));create policy "members read collection activity" on public.collection_activity for select to authenticated using(private.is_active_member(organisation_id));
alter table public.invoices add column if not exists disputed boolean not null default false;
create table if not exists public.promise_to_pay (id uuid primary key default gen_random_uuid(),organisation_id uuid not null references public.organisations(id) on delete cascade,contact_id uuid not null references public.crm_contacts(id),invoice_id uuid references public.invoices(id) on delete set null,promised_amount numeric(14,2) not null check(promised_amount>0),promised_date date not null,source text not null,status text not null default 'active' check(status in ('active','fulfilled','broken','cancelled')),note text,created_at timestamptz not null default now());
create index if not exists promise_to_pay_org_date_idx on public.promise_to_pay(organisation_id,promised_date);
alter table public.promise_to_pay enable row level security;
create policy "members manage promises" on public.promise_to_pay for all to authenticated using(private.is_active_member(organisation_id)) with check(private.is_active_member(organisation_id));
create unique index if not exists collection_reminder_idempotency_idx on public.collection_activity(organisation_id,invoice_id,activity_type,stage) where activity_type='reminder_sent';
drop policy if exists "members create approvals" on public.approvals; create policy "members create approvals" on public.approvals for insert to authenticated with check(private.is_active_member(organisation_id));

